void *old_addr = ...; // Page aligned
size_t old_size = 4096;
size_t new_size = 8192;
void *target_addr = (void *)0x200000; // New requested location

// Resize mapping, allowing relocation (MAYMOVE)
int flags_resize = MREMAP_MAYMOVE;

void *new_addr = mremap(
    old_addr,
    old_size,
    new_size,
    flags_resize
);

// Resize and forcibly move (requires 5th argument)
int flags_reloc = MREMAP_MAYMOVE | MREMAP_FIXED;

new_addr = mremap(
    old_addr,
    old_size,
    new_size,
    flags_reloc,
    target_addr
);

if (new_addr == (void *)-1) { /* error */ }
